    for doc_id, title, domain, focus, spec, sales_use, syn_int in web_docs:
        content.append(f"#### ДОСЬЕ ВЕБ-ДОКУМЕНТА: [{doc_id}] {title}\n")
        content.append(f"- **Первоисточник:** `{domain}` | **Идентификатор:** `{doc_id}`")
        content.append(f"- **Тематическая специализация:** {focus}\n")
